<?php
namespace LlmsCatalog\Audit;

/** Bounded robots and sitemap diagnostics for one authorized shop host. */
final class SurfaceAuditor
{
    public function audit(string $baseUrl,array $hosts,array $sampleUrls,int $shopId,string $language): array
    {
        $now=gmdate(DATE_ATOM);$findings=[];$base=rtrim($baseUrl,'/');$fetch=new BoundedHttpFetcher();$robotsUrl=$base.'/robots.txt';$sitemapUrls=[];
        try{$r=$fetch->fetch($robotsUrl,$hosts,262144);if($r['status']!==200)$findings[]=new AuditFinding('ROBOTS_UNAVAILABLE','medium','robots',$shopId,$language,$robotsUrl,null,$r['status'],'HTTP 200',[],'Hosting/server','Serve a valid root robots.txt where crawler policy is intentional.','robots-v1',false,$now);else{$groups=(new RobotsInspector())->rules($r['body']);if(!$groups)$findings[]=new AuditFinding('ROBOTS_NO_GROUPS','medium','robots',$shopId,$language,$robotsUrl,null,'no user-agent groups','At least one parseable group',[],'Hosting/server','Review the root robots.txt syntax.','robots-v1',false,$now);foreach(['Googlebot','bingbot','OAI-SearchBot','GPTBot','ChatGPT-User','ClaudeBot','Claude-SearchBot','Claude-User','PerplexityBot','Perplexity-User'] as $agent){foreach(['/','/products/','/img/','/llms.txt'] as $path){$decision=(new RobotsInspector())->access($r['body'],$agent,$path);$findings[]=new AuditFinding('ROBOTS_ACCESS_MATRIX','info','robots',$shopId,$language,$robotsUrl,null,['agent'=>$agent,'path'=>$path,'allowed'=>$decision],'Review crawler intent; robots does not verify WAF reachability',[],'Merchant/hosting','Confirm search, training, and user-fetch policy separately.','robots-v1',false,$now);}}foreach($groups as $g)foreach($g['rules'] as $rule)if($rule['directive']==='sitemap'&&$rule['value']!=='')$sitemapUrls[]=$rule['value'];}}
        catch(\Throwable $e){$findings[]=new AuditFinding('ROBOTS_FETCH_FAILED','medium','robots',$shopId,$language,$robotsUrl,null,'bounded same-host fetch failed','Reachable shop robots.txt',[],'Hosting/server','Check the root robots.txt response and authorized host.','robots-v1',false,$now);}
        if(!$sitemapUrls)$findings[]=new AuditFinding('SITEMAP_UNDECLARED','info','sitemap',$shopId,$language,$robotsUrl,null,null,'A sitemap reference is available from robots.txt or shop configuration',[],'Merchant/sitemap owner','Add the existing sitemap URL to robots.txt if the shop uses one.','sitemap-v1',false,$now);
        foreach(array_slice(array_unique($sitemapUrls),0,2) as $sitemapUrl){try{$r=$fetch->fetch($sitemapUrl,$hosts,2097152);if($r['status']!==200)throw new \RuntimeException('status');$body=$r['body'];if(str_ends_with(strtolower((string)parse_url($sitemapUrl,PHP_URL_PATH)),'.gz')||substr($body,0,2)==="\x1f\x8b"){$body=@gzdecode($body,2097152);if($body===false)throw new \RuntimeException('invalid gzip');}$parsed=(new SitemapReader())->read($body,100000);$set=array_column($parsed['items'],'url');foreach($set as $listed){$listedHost=strtolower((string)parse_url($listed,PHP_URL_HOST));if(!in_array($listedHost,array_map('strtolower',$hosts),true))$findings[]=new AuditFinding('SITEMAP_OFF_HOST_URL','high','sitemap',$shopId,$language,$sitemapUrl,null,$listed,'Sitemap URLs belong to this shop host',[],'Sitemap owner','Remove cross-host or incorrectly configured URLs from the sitemap.','sitemap-v1',false,$now);}foreach($sampleUrls as $url)if(!in_array($url,$set,true))$findings[]=new AuditFinding('SITEMAP_SAMPLE_MISSING','medium','sitemap',$shopId,$language,$sitemapUrl,null,$url,'Sample canonical URL appears in sitemap',[],'Sitemap owner','Review whether this public canonical page should appear in the sitemap.','sitemap-v1',false,$now);if($parsed['truncated'])$findings[]=new AuditFinding('SITEMAP_TRUNCATED','info','sitemap',$shopId,$language,$sitemapUrl,null,100000,'Bounded inspection limit',[],'Sitemap owner','Large sitemap inventory was truncated at 100,000 URLs.','sitemap-v1',false,$now);if($parsed['index'])foreach(array_slice($set,0,2) as $child){try{$childResponse=$fetch->fetch($child,$hosts,2097152);if($childResponse['status']===200)(new SitemapReader())->read($childResponse['body'],100000);}catch(\Throwable $e){$findings[]=new AuditFinding('SITEMAP_CHILD_FAILED','medium','sitemap',$shopId,$language,$child,null,'fetch or parse failed','Reachable same-host child sitemap',[],'Sitemap owner','Review the child sitemap URL and response.','sitemap-v1',false,$now);}}}catch(\Throwable $e){$findings[]=new AuditFinding('SITEMAP_FETCH_FAILED','medium','sitemap',$shopId,$language,$sitemapUrl,null,'fetch or parse failed','Well-formed bounded sitemap',[],'Sitemap owner','Review same-host sitemap availability and XML syntax.','sitemap-v1',false,$now);}}
        return $findings;
    }
}
